  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=Inter:wght@400;500;600&display=swap" rel="stylesheet">
  <style>
    :root {
      --primary: #1a1a2e;
      --primary-dark: #0f0f1a;
      --accent: #E6FF32;
      --accent-hover: #d4eb2a;
      --secondary: #7F2A23;
      --text: #1a1a2e;
      --text-light: #6b7280;
      --bg: #ffffff;
      --bg-secondary: #f8fafc;
      --border: #e5e7eb;
      --success: #10b981;
    }

    * { margin: 0; padding: 0; box-sizing: border-box; }

    body {
      font-family: 'Plus Jakarta Sans', sans-serif;
      background: var(--bg);
      color: var(--text);
      line-height: 1.6;
      overflow-x: hidden;
    }

    .container { max-width: 1280px; margin: 0 auto; padding: 0 24px; }

    .nav {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(255,255,255,0.95);
      backdrop-filter: blur(20px);
      border-bottom: 1px solid var(--border);
    }

    .nav-inner { display: flex; align-items: center; justify-content: space-between; padding: 16px 0; gap: 32px; }

    .nav-logo { font-size: 24px; font-weight: 800; color: var(--primary); text-decoration: none; display: flex; align-items: center; gap: 8px; }
    .nav-logo svg { width: 32px; height: 32px; }

    .nav-links { display: flex; gap: 32px; list-style: none; }
    .nav-links a { color: var(--text); text-decoration: none; font-weight: 500; font-size: 15px; transition: color 0.2s; }
    .nav-links a:hover { color: var(--secondary); }
    .nav-links a.active { color: var(--secondary); }

    .nav-actions { display: flex; align-items: center; gap: 16px; }

    .btn {
      display: inline-flex; align-items: center; justify-content: center;
      padding: 12px 24px; border-radius: 12px; font-weight: 600; font-size: 15px;
      text-decoration: none; cursor: pointer; border: none; transition: all 0.2s;
    }

    .btn-primary { background: var(--accent); color: var(--primary); }
    .btn-primary:hover { background: var(--accent-hover); transform: translateY(-2px); }
    .btn-secondary { background: var(--primary); color: white; }
    .btn-secondary:hover { background: var(--primary-dark); }

    .hero {
      padding: 80px 0 60px;
      background: linear-gradient(135deg, #f8fafc 0%, #ffffff 100%);
      position: relative;
      overflow: hidden;
    }

    .hero::before {
      content: '';
      position: absolute;
      top: -50%;
      right: -20%;
      width: 600px;
      height: 600px;
      background: radial-gradient(circle, rgba(230,255,50,0.1) 0%, transparent 70%);
      pointer-events: none;
    }

    .hero-content { max-width: 800px; margin: 0 auto; text-align: center; }

    .hero-badge {
      display: inline-flex; align-items: center; gap: 8px;
      background: var(--primary); color: white;
      padding: 8px 16px; border-radius: 100px;
      font-size: 13px; font-weight: 600; margin-bottom: 24px;
    }

    .hero h1 {
      font-size: clamp(40px, 6vw, 56px);
      font-weight: 800; line-height: 1.1;
      margin-bottom: 20px; color: var(--primary);
    }

    .hero-subtitle {
      font-size: 18px; color: var(--text-light);
      margin-bottom: 32px; max-width: 600px; margin-left: auto; margin-right: auto;
    }

    .hero-cta { display: flex; gap: 16px; justify-content: center; }

    .stats-bar { background: var(--primary); padding: 48px 0; }

    .stats-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; text-align: center; }

    .stat-item h3 { font-size: 48px; font-weight: 800; color: var(--accent); margin-bottom: 8px; }
    .stat-item p { color: rgba(255,255,255,0.8); font-size: 16px; }

    .section { padding: 80px 0; }
    .section-header { text-align: center; margin-bottom: 56px; }
    .section-header h2 { font-size: 40px; font-weight: 700; margin-bottom: 16px; }
    .section-header p { font-size: 18px; color: var(--text-light); max-width: 600px; margin: 0 auto; }

    .value-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }

    .value-card {
      background: white; border: 1px solid var(--border);
      border-radius: 20px; padding: 32px; transition: all 0.3s;
    }

    .value-card:hover {
      border-color: var(--accent);
      box-shadow: 0 12px 40px rgba(0,0,0,0.08);
      transform: translateY(-4px);
    }

    .value-icon {
      width: 56px; height: 56px;
      background: linear-gradient(135deg, var(--accent) 0%, var(--success) 100%);
      border-radius: 16px; display: flex;
      align-items: center; justify-content: center;
      margin-bottom: 20px;
    }

    .value-icon svg { width: 28px; height: 28px; stroke: var(--primary); }

    .value-card h3 { font-size: 18px; font-weight: 700; margin-bottom: 8px; }
    .value-card p { font-size: 14px; color: var(--text-light); line-height: 1.5; }

    .create-section { background: var(--bg-secondary); }

    .create-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 48px; align-items: center; }

    .create-content h3 { font-size: 28px; font-weight: 700; margin-bottom: 16px; }
    .create-content p { color: var(--text-light); margin-bottom: 24px; font-size: 16px; }

    .create-steps { list-style: none; }

    .create-step {
      display: flex; gap: 16px; align-items: flex-start;
      margin-bottom: 24px; padding: 20px;
      background: white; border-radius: 12px;
    }

    .step-number {
      width: 40px; height: 40px;
      background: var(--accent); border-radius: 10px;
      display: flex; align-items: center; justify-content: center;
      font-weight: 700; color: var(--primary); flex-shrink: 0;
    }

    .step-content h4 { font-size: 16px; font-weight: 600; margin-bottom: 4px; }
    .step-content p { font-size: 14px; color: var(--text-light); }

    .business-section { background: var(--primary); color: white; }

    .business-section .section-header h2 { color: white; }
    .business-section .section-header p { color: rgba(255,255,255,0.7); }

    .business-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 32px; }

    .business-card {
      background: rgba(255,255,255,0.1);
      border-radius: 20px; padding: 32px;
      backdrop-filter: blur(10px);
    }

    .business-card h3 { font-size: 20px; font-weight: 700; margin-bottom: 12px; color: white; }
    .business-card p { color: rgba(255,255,255,0.8); font-size: 15px; line-height: 1.6; }

    .integrations-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 16px; }

    .integration-item {
      background: white; border: 1px solid var(--border);
      border-radius: 12px; padding: 20px;
      display: flex; align-items: center; justify-content: center;
      font-size: 14px; font-weight: 600; color: var(--text-light);
      transition: all 0.3s;
    }

    .integration-item:hover { border-color: var(--accent); color: var(--primary); }

    .testimonials-section { background: var(--primary); color: white; padding: 80px 0; }
    .testimonials-section .section-header h2 { color: white; }
    .testimonials-section .section-header p { color: rgba(255,255,255,0.7); }

    .carousel-container { position: relative; overflow: hidden; }

    .carousel-track { display: flex; gap: 24px; transition: transform 0.5s ease; }

    .testimonial-card {
      flex: 0 0 calc(33.333% - 16px);
      background: rgba(255,255,255,0.1);
      border-radius: 20px; padding: 32px;
      backdrop-filter: blur(10px);
    }

    .testimonial-quote { font-size: 16px; line-height: 1.6; margin-bottom: 24px; color: rgba(255,255,255,0.9); }

    .testimonial-author { display: flex; align-items: center; gap: 12px; }

    .testimonial-avatar {
      width: 48px; height: 48px;
      background: var(--accent); border-radius: 50%;
      display: flex; align-items: center; justify-content: center;
      font-weight: 700; color: var(--primary);
    }

    .testimonial-name { font-weight: 600; font-size: 15px; }
    .testimonial-role { font-size: 13px; color: rgba(255,255,255,0.6); }

    .carousel-controls { display: flex; justify-content: center; gap: 16px; margin-top: 32px; }

    .carousel-btn {
      width: 48px; height: 48px; border-radius: 50%;
      background: rgba(255,255,255,0.1); border: none;
      cursor: pointer; display: flex;
      align-items: center; justify-content: center;
      transition: all 0.3s;
    }

    .carousel-btn:hover { background: var(--accent); }
    .carousel-btn svg { width: 20px; height: 20px; stroke: white; }
    .carousel-btn:hover svg { stroke: var(--primary); }

    .carousel-dots { display: flex; justify-content: center; gap: 8px; margin-top: 24px; }

    .carousel-dot {
      width: 10px; height: 10px; border-radius: 50%;
      background: rgba(255,255,255,0.3); cursor: pointer;
      transition: all 0.3s;
    }

    .carousel-dot.active { background: var(--accent); }

    .file-types-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 16px; }

    .file-type-item {
      background: white; border: 1px solid var(--border);
      border-radius: 12px; padding: 24px;
      text-align: center; font-size: 14px; font-weight: 600;
      transition: all 0.3s;
    }

    .file-type-item:hover {
      border-color: var(--accent);
      transform: translateY(-2px);
    }

    .file-type-icon {
      width: 48px; height: 48px;
      background: var(--bg-secondary);
      border-radius: 12px; margin: 0 auto 12px;
      display: flex; align-items: center; justify-content: center;
    }

    .file-type-icon svg { width: 24px; height: 24px; stroke: var(--primary); }

    .cta-banner {
      background: linear-gradient(135deg, var(--primary) 0%, #2d2d4a 100%);
      padding: 80px 0; text-align: center; color: white;
    }

    .cta-banner h2 { font-size: 40px; margin-bottom: 16px; }
    .cta-banner p { font-size: 18px; opacity: 0.8; margin-bottom: 32px; }
    .cta-banner .btn { background: var(--accent); color: var(--primary); font-size: 18px; padding: 16px 32px; }

    .faq-list { max-width: 800px; margin: 0 auto; }

    .faq-item { border: 1px solid var(--border); border-radius: 12px; margin-bottom: 12px; overflow: hidden; }

    .faq-question {
      width: 100%; padding: 20px 24px;
      background: white; border: none;
      text-align: left; font-size: 16px; font-weight: 600;
      cursor: pointer; display: flex;
      justify-content: space-between; align-items: center;
      transition: all 0.3s;
    }

    .faq-question:hover { background: var(--bg-secondary); }
    .faq-question svg { width: 20px; height: 20px; stroke: var(--text-light); transition: transform 0.3s; }

    .faq-item.open .faq-question svg { transform: rotate(180deg); }

    .faq-answer { max-height: 0; overflow: hidden; transition: max-height 0.3s ease; }

    .faq-item.open .faq-answer { max-height: 200px; }

    .faq-answer-content { padding: 0 24px 20px; color: var(--text-light); font-size: 15px; line-height: 1.6; }

    .footer {
      background: var(--primary-dark);
      color: white; padding: 64px 0 32px;
    }

    .footer-grid { display: grid; grid-template-columns: 2fr repeat(3, 1fr); gap: 48px; margin-bottom: 48px; }

    .footer-brand h3 { font-size: 24px; margin-bottom: 16px; display: flex; align-items: center; gap: 8px; }
    .footer-brand p { color: rgba(255,255,255,0.7); font-size: 14px; line-height: 1.6; max-width: 300px; }

    .footer-col h4 { font-size: 14px; text-transform: uppercase; letter-spacing: 1px; margin-bottom: 20px; color: rgba(255,255,255,0.5); }

    .footer-col ul { list-style: none; }
    .footer-col li { margin-bottom: 12px; }
    .footer-col a { color: rgba(255,255,255,0.8); text-decoration: none; font-size: 14px; transition: color 0.2s; }
    .footer-col a:hover { color: var(--accent); }

    .footer-bottom {
      border-top: 1px solid rgba(255,255,255,0.1);
      padding-top: 32px;
      display: flex; justify-content: space-between;
      align-items: center; font-size: 14px;
      color: rgba(255,255,255,0.5);
    }

    .footer-legal { display: flex; gap: 24px; }
    .footer-legal a { color: rgba(255,255,255,0.5); text-decoration: none; }
    .footer-legal a:hover { color: white; }

    @media (max-width: 1024px) {
      .value-grid { grid-template-columns: repeat(2, 1fr); }
      .create-grid { grid-template-columns: 1fr; }
      .business-grid { grid-template-columns: 1fr; }
      .file-types-grid { grid-template-columns: repeat(4, 1fr); }
      .integrations-grid { grid-template-columns: repeat(4, 1fr); }
    }

    @media (max-width: 768px) {
      .nav-links { display: none; }
      .hero h1 { font-size: 32px; }
      .stats-grid { grid-template-columns: 1fr; gap: 24px; }
      .value-grid { grid-template-columns: 1fr; }
      .file-types-grid { grid-template-columns: repeat(2, 1fr); }
      .integrations-grid { grid-template-columns: repeat(3, 1fr); }
      .footer-grid { grid-template-columns: 1fr; }
      .footer-bottom { flex-direction: column; gap: 16px; }
      .testimonial-card { flex: 0 0 100%; }
    }
  </style>
</head>
