  <script>
    const carouselTrack = document.querySelector('.carousel-track');
    const prevBtn = document.getElementById('prevBtn');
    const nextBtn = document.getElementById('nextBtn');
    const dots = document.querySelectorAll('.carousel-dot');
    let currentIndex = 0;

    function updateCarousel() {
      const cardWidth = carouselTrack.querySelector('.testimonial-card').offsetWidth + 24;
      carouselTrack.style.transform = `translateX(-${currentIndex * cardWidth}px)`;
      dots.forEach((dot, i) => dot.classList.toggle('active', i === currentIndex));
    }

    prevBtn.addEventListener('click', () => { currentIndex = Math.max(0, currentIndex - 1); updateCarousel(); });
    nextBtn.addEventListener('click', () => { currentIndex = Math.min(2, currentIndex + 1); updateCarousel(); });
    dots.forEach((dot, i) => dot.addEventListener('click', () => { currentIndex = i; updateCarousel(); }));

    const faqItems = document.querySelectorAll('.faq-item');
    faqItems.forEach(item => {
      const question = item.querySelector('.faq-question');
      question.addEventListener('click', () => {
        const isOpen = item.classList.contains('open');
        faqItems.forEach(i => i.classList.remove('open'));
        if (!isOpen) item.classList.add('open');
      });
    });
  </script>
